  var stock=w.Features.Single(f=>w.IsSecuringSite(f));stock.Contents.MaxSlots=stock.Contents.Items.Count;serial=w.NextItemInstanceNumber;minute=w.CampaignMinutes;check(!w.ClaimContract(a,Sweep)&&w.NextItemInstanceNumber==serial&&w.CampaignMinutes==minute&&w.ContractXpAwarded==0,"Phase 20 full reward storage rejects the whole turn-in before costs");stock.Contents.MaxSlots=32;
  check(w.ClaimContract(a,Sweep)&&w.ContractXpAwarded==8&&w.Quest(Sweep)!.Status==QuestStatus.Completed&&stock.Contents.Count("item.commodity.026")==2,"Phase 20 one report grants the authored shared XP and finite stockpile reward");
  check(stock.Contents.Items.Where(s=>s.ItemId=="item.commodity.026").All(s=>s.ResourceUnits.Count==0)&&w.ResourceXpAwarded==0,"Phase 20 quest rewards do not invent scavenging credit");serial=w.NextItemInstanceNumber;check(!w.ClaimContract(a,Sweep)&&w.ContractXpAwarded==8&&w.NextItemInstanceNumber==serial,"Phase 20 duplicate reports cannot replay rewards");
