  var timed=CampaignLoader.Clone(fixture);timed.Story!.Contracts[0].DeadlineMinutes=1;w=Fresh(timed);w.AcceptContract(w.PartyLeader,Sweep);w.AdvanceCampaignSeconds(59);check(w.ContractStatus(Sweep)=="Active","Phase 20 deadlines do not expire early");w.AdvanceCampaignSeconds(1);check(w.ContractStatus(Sweep)=="Failed"&&w.Quest(Sweep)!.Status==QuestStatus.Failed&&!w.ClaimContract(w.PartyLeader,Sweep),"Phase 20 exact campaign-time deadline failure persists and blocks rewards");w.Save(path);check(World.Load(path).ContractStatus(Sweep)=="Failed","Phase 20 reloading never resets an accepted deadline");
  var protection=CampaignLoader.Clone(fixture);protection.Story!.Contracts[0].FailureActorId=protection.Actors.First(a=>!a.Enemy).Id;w=Fresh(protection);w.AcceptContract(w.PartyLeader,Sweep);w.PartyLeader.Character.SetCondition("dead","Dead",true);w.SyncCampaignObjectives();check(w.ContractStatus(Sweep)=="Failed","Phase 20 authored protected-survivor death fails the contract");
  w=Fresh();Finish(w);a=w.PartyLeader;w.ClaimContract(a,Sweep);w.AcceptContract(a,Battery);w.AdvanceCampaignSeconds(3600);w.AdvanceCampaignSeconds(3600);check(w.ContractStatus(Battery)=="Failed"&&w.ContractStatus(Wire)=="Available"&&w.AcceptContract(a,Wire),"Phase 20 a failed timed choice permits its unchosen alternative without retrying the failed contract");
  foreach(var kind in new[]{"area-visited","rescued","flag","item-held","secured-sv","encounter-cleared"})
  {
   var copy=CampaignLoader.Clone(fixture);var q=copy.Story!.Contracts[0];q.Goals=[new(){Id="goal.test",Text="Test goal",Kind=kind,Quantity=1,TargetId=kind switch{"area-visited"=>copy.StartAreaId,"rescued"=>copy.Actors.First(a=>!a.Enemy).Id,"flag"=>"flag.mall.shelter","item-held"=>"item.mall.pistol","encounter-cleared"=>"encounter.mall.cafe",_=>""}}];if(kind=="encounter-cleared")q.Goals[0].TargetId=copy.Encounters[0].Id;w=Fresh(copy);w.AcceptContract(w.PartyLeader,Sweep);var st=w.ContractStates.Single();int expected=kind is "secured-sv" or "encounter-cleared"?0:1;check(w.ContractGoalProgress(q,st,q.Goals[0])==expected,"Phase 20 typed objective uses current facts: "+kind);
  }
  var duplicateCost=CampaignLoader.Clone(fixture);duplicateCost.Story!.Contracts[2].Goals=[new(){Id="goal.wire.one",Text="First spool",Kind="deliver-items",TargetId="item.commodity.084"},new(){Id="goal.wire.two",Text="Second spool",Kind="deliver-items",TargetId="item.commodity.084"}];
  w=Fresh(duplicateCost);Finish(w);w.ClaimContract(w.PartyLeader,Sweep);w.AcceptContract(w.PartyLeader,Wire);w.PartyLeader.Inventory.Add(new ItemStack{ItemId="item.commodity.084",CampaignGear=w.ResolveItemDefinition("item.commodity.084"),Quantity=1});serial=w.NextItemInstanceNumber;
  check(!w.ClaimContract(w.PartyLeader,Wire)&&w.PartyLeader.Inventory.Count("item.commodity.084")==1&&w.ContractXpAwarded==8&&w.NextItemInstanceNumber==serial,"Phase 20 repeated item goals aggregate their physical delivery cost atomically");
  w.PartyLeader.Inventory.Add(new ItemStack{ItemId="item.commodity.084",CampaignGear=w.ResolveItemDefinition("item.commodity.084"),Quantity=1});check(w.ClaimContract(w.PartyLeader,Wire)&&w.PartyLeader.Inventory.Count("item.commodity.084")==0&&w.ContractXpAwarded==12,"Phase 20 aggregated delivery consumes both real units once");
  var flagged=CampaignLoader.Clone(fixture);flagged.Story!.Contracts[0].FailureFlag="flag.mall.maintenance-log";w=Fresh(flagged);w.AcceptContract(w.PartyLeader,Sweep);w.PartyLeader.Pos=new(22,28);w.Reveal();w.Interact(w.Features.Single(f=>f.Id=="feature.mall.maintenance-manifest"));
  check(w.ContractStatus(Sweep)=="Failed"&&w.ContractXpAwarded==0&&!w.AcceptContract(w.PartyLeader,Sweep),"Phase 20 authored failure flag resolves permanently without rewards");
  w=Fresh();Finish(w);w.ClaimContract(w.PartyLeader,Sweep);w.Save(path);string saved=File.ReadAllText(path);
  void Reject(Action<JsonNode> change,string why){var n=JsonNode.Parse(saved)!;change(n);File.WriteAllText(path,n.ToJsonString());bool rejected=false;try{World.Load(path);}catch{rejected=true;}check(rejected,"Phase 20 rejects "+why);}
  Reject(n=>n["ContractXpAwarded"]=16,"inconsistent reward ledger");Reject(n=>n["ContractStates"]![0]!["Progress"]![0]=999,"out-of-range goal progress");Reject(n=>n["ContractStates"]![0]!["Id"]="unknown","unknown contract state");Reject(n=>n["EncounterPlanStates"]![0]!["NextWave"]=3,"out-of-range wave cursor");Reject(n=>n["EncounterPlanStates"]![0]!["NextWave"]=1,"unreleased future actors");Reject(n=>n["Campaign"]!["Story"]=null,"story state without opt-in");
